async function renderCategoryGrid() {
  await loadTokens();
  const metro = document.getElementById('metro').value;
  const grid = document.getElementById('category-grid');
  const hiddenCat = document.getElementById('category');

  const currentSelected = hiddenCat.value;
  grid.innerHTML = '';

  CATEGORIES.forEach(cat => {
    // Check if locked in this metro
    const isLocked = Object.values(activeTokens).some(
      sub => sub.metro && sub.metro.toLowerCase() === metro.toLowerCase() && 
             sub.category && sub.category.toLowerCase().includes(cat.id.toLowerCase().slice(0, 10))
    );

    const card = document.createElement('div');
    const isSelected = (!isLocked && currentSelected === cat.id);

