import json

with open('docs/raw_transcript_full.jsonl') as f:
    lines = [json.loads(l) for l in f]

turns = []
current_turn = None

for step in lines:
    stype = step.get('type')
    if stype == 'USER_INPUT':
        if current_turn:
            turns.append(current_turn)
        current_turn = {
            'user': step,
            'model_steps': [],
            'tools': []
        }
    elif current_turn is not None:
        if stype == 'PLANNER_RESPONSE':
            current_turn['model_steps'].append(step)
            for tc in step.get('tool_calls', []):
                current_turn['tools'].append(tc.get('name', 'tool'))

if current_turn:
    turns.append(current_turn)

print(f'Total user turns identified: {len(turns)}')
for i, t in enumerate(turns[:5]):
    user_txt = t['user'].get('content', '')[:80].replace('\n', ' ')
    last_resp = ''
    for s in reversed(t['model_steps']):
        c = s.get('content', '')
        if c and not s.get('tool_calls'):
            last_resp = c[:80].replace('\n', ' ')
            break
    print(f'Turn {i+1}: Tools used: {len(t[\"tools\"])} | User: {user_txt} | Resp: {last_resp}')
"

